type SRSSpatialRelationInfo struct { // [{'type': 'ServCellIndex', 'name': 'servingCellId', 'optional': True}, {'type': 'CHOICE', 'members': [{'type': 'SSB-Index', 'name': 'ssb-Index'}, {'type': 'NZP-CSI-RS-ResourceId', 'name': 'csi-RS-Index'}, {'type': 'SEQUENCE', 'members': [{'type': 'SRS-ResourceId', 'name': 'resourceId'}, {'type': 'BWP-Id', 'name': 'uplinkBWP'}], 'name': 'srs'}], 'name': 'referenceSignal'}]
    ServingCellId *ServCellIndex
    ReferenceSignal SRSSpatialRelationInfo_ReferenceSignal
}

func (self * SRSSpatialRelationInfo) Unpack(stream *Stream) {
    servingCellId_flag := 0x00000001
    _flags := 0
    _flags = stream.get_flags(1)
    if (servingCellId_flag & _flags) == servingCellId_flag { //cond2
        self.ServingCellId = &ServCellIndex{}//7{'type': 'ServCellIndex', 'name': 'servingCellId', 'optional': True}
        self.ServingCellId.Unpack(stream)// p8
    }
    var Unpack_referenceSignal = func(stream *Stream, self *SRSSpatialRelationInfo_ReferenceSignal) {
        //coptions := []string{"ssb-Index","csi-RS-Index","srs","Unknown"}
        choice := stream.get_choice(2, 0, 3)
        if choice == 0 { //ch1
            self.SsbIndex = &SSBIndex{}//cho6
            self.SsbIndex.Unpack(stream)
        } else if choice == 1 { //ch2
            self.CsiRSIndex = &NZPCSIRSResourceId{}//cho6
            self.CsiRSIndex.Unpack(stream)
        } else if choice == 2 { //ch2
            var Unpack_srs = func(stream *Stream, self *SRSSpatialRelationInfo_ReferenceSignal_Srs) { //[{'type': 'SRS-ResourceId', 'name': 'resourceId'}, {'type': 'BWP-Id', 'name': 'uplinkBWP'}]
                self.ResourceId.Unpack(stream)// p8
                self.UplinkBWP.Unpack(stream)// p8
                return
            }
            self.Srs = &SRSSpatialRelationInfo_ReferenceSignal_Srs{}//cho4
            Unpack_srs(stream, self.Srs);
        }//end of if else

    }
    Unpack_referenceSignal(stream, &self.ReferenceSignal)// p2
    return
}

func (self * SRSSpatialRelationInfo) Pack(stream *Stream) {
    const servingCellId_flag uint = 0x00000001
    _flagReserve := stream.reserve_flags(1)
    var _extReserve uint32 = 0
    var _extPresent bool = false
    var _flags uint = 0
    var _extflags uint = 0
    if self.ServingCellId != nil { 
        _flags |= servingCellId_flag
        self.ServingCellId.Pack(stream)
    }//end of optional
    var Pack_referenceSignal = func(stream *Stream, self SRSSpatialRelationInfo_ReferenceSignal) {
        if self.SsbIndex != nil {
            stream.set_choice(0, 2, 0, 3)
            self.SsbIndex.Pack(stream)//2
        } else if self.CsiRSIndex != nil {
            stream.set_choice(1, 2, 0, 3)
            self.CsiRSIndex.Pack(stream)//2
        } else if self.Srs != nil {
            stream.set_choice(2, 2, 0, 3)
            var Pack_srs = func(stream *Stream, self SRSSpatialRelationInfo_ReferenceSignal_Srs) {//seq
                self.ResourceId.Pack(stream)
                self.UplinkBWP.Pack(stream)
            }//end
            Pack_srs(stream, *self.Srs)//1
        }

    }
    Pack_referenceSignal(stream, self.ReferenceSignal) //f2
    if _extPresent { stream.set_flags(_extflags, _extReserve, 0) }
    stream.set_flags(_flags, _flagReserve, 1)
}//end

